from decimal import Decimal, ROUND_HALF_EVEN

def compute_net_fee(principal: str, bps: int, rebate_bps: int = 0) -> str:
    amt = Decimal(principal)
    effective_bps = Decimal(bps - rebate_bps) / Decimal(10000)
    fee = (amt * effective_bps).quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
    return str(fee)

from decimal import Decimal, ROUND_HALF_EVEN

def compute_net_fee(principal: str, bps: int, rebate_bps: int = 0) -> str:
    amt = Decimal(principal)
    effective_bps = Decimal(bps - rebate_bps) / Decimal(10000)
    fee = (amt * effective_bps).quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
    return str(fee)

